CREATE TABLE `Category` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `Name` VARCHAR(25) NOT NULL,
  `Description` VARCHAR(255) NULL,
  `Created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Updated_at` TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `Status` VARCHAR(50) NOT NULL DEFAULT 'ACTIVE',
  PRIMARY KEY (`ID`),
  UNIQUE KEY `uk_Category_Name` (`Name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `Product` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `Name` VARCHAR(50) NOT NULL UNIQUE,
  `Description` VARCHAR(255) NULL,
  `Release_Year` INT NULL,
  `Rating` DECIMAL(2,1) NULL,
  `warranty_months` INT NOT NULL,
  `Updated_at` TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `Created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `BrandID` INT NOT NULL,
  `Status` VARCHAR(50) NOT NULL DEFAULT 'ACTIVE',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `Product_Category` (
  `ProductID` INT NOT NULL,
  `CategoryID` INT NOT NULL,
  PRIMARY KEY (`ProductID`, `CategoryID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `ProductVariant` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `ProductID` INT NOT NULL,
  `RAM_GB` INT NOT NULL,
  `Storage_GB` INT NOT NULL,
  `ColorName` VARCHAR(50) NOT NULL,
  `SKU` VARCHAR(255) NOT NULL,
  `Selling_price` DECIMAL(12,2) NOT NULL,
  `Latest_cost` DECIMAL(12,2) NOT NULL,
  Image VARCHAR(255) NULL,
  BackImage VARCHAR(255) NULL,
  `Status` VARCHAR(50) NOT NULL DEFAULT 'ACTIVE',
  `Created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Updated_at` TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `uk_ProductVariant_option` (`ProductID`, `RAM_GB`, `Storage_GB`, `ColorName`),
  UNIQUE KEY `uk_ProductVariant_Image` (`Image`),
  UNIQUE KEY `uk_ProductVariant_SKU` (`SKU`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `Inventory` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `ProductVariantID` INT NOT NULL,
  `Amount` INT NOT NULL,
  `Min_amount` INT NULL,
  `Max_amount` INT NULL,
  `Updated_at` TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `Status` VARCHAR(50) NOT NULL DEFAULT 'ACTIVE',
  PRIMARY KEY (`ID`),
  UNIQUE KEY `uk_Inventory_VariantID` (`ProductVariantID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `Brand` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `Name` VARCHAR(50) NOT NULL,
  `Description` VARCHAR(255) NULL,
  `Created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Updated_at` TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `Status` VARCHAR(50) NOT NULL DEFAULT 'ACTIVE',
  PRIMARY KEY (`ID`),
  UNIQUE KEY `uk_Brand_Name` (`Name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `Supplier` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `Name` VARCHAR(50) NOT NULL,
  `Address` VARCHAR(255) NOT NULL,
  `Phone` VARCHAR(255) NOT NULL,
  `Description` VARCHAR(255) NULL,
  `Note` VARCHAR(255) NULL,
  `Created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Updated_at` TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `Status` VARCHAR(50) NOT NULL DEFAULT 'ACTIVE',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `Supplier_ProductVariant` (
  `SupplierID` INT NOT NULL,
  `ProductVariantID` INT NOT NULL,
  PRIMARY KEY (`SupplierID`, `ProductVariantID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 

CREATE TABLE `User` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `Username` VARCHAR(255) NOT NULL,
  `Password` VARCHAR(255) NOT NULL,
  `Name` VARCHAR(255) NOT NULL,
  `Phone` VARCHAR(255) NOT NULL,
  `Address` VARCHAR(255) NOT NULL,
  Image VARCHAR(255) NULL,
  BackImage VARCHAR(255) NULL,
  `Age` INT NULL,
  `Email` VARCHAR(255) NOT NULL,
  `RoleID` INT NOT NULL,
  `Status` VARCHAR(50) NOT NULL DEFAULT 'ACTIVE',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `PasswordResetToken` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `UserID` INT NOT NULL,
  `Token` VARCHAR(64) NOT NULL,
  `Expires_at` DATETIME NOT NULL,
  `Used_at` DATETIME NULL,
  `Created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `uq_PasswordResetToken_Token` (`Token`),
  KEY `idx_PasswordResetToken_UserID` (`UserID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `Role` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `Name` VARCHAR(255) NOT NULL,
  `Status` VARCHAR(50) NOT NULL DEFAULT 'ACTIVE',
  `Created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Updated_at` TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `Permisson` (
  `ID` INT NOT NULL,
  `Name`VARCHAR(255) NOT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 

CREATE TABLE `Permisson_Role` (
  `PermissonID` INT NOT NULL,
  `RoleID` INT NOT NULL,
  PRIMARY KEY (`PermissonID`, `RoleID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `Wishlist` (
  `UserID` INT NOT NULL,
  `ProductVariantID` INT NOT NULL,
  PRIMARY KEY (`UserID`, `ProductVariantID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `Cart` (
  `UserID` INT NOT NULL,
  `ProductVariantID` INT NOT NULL,
  `Amount` INT NOT NULL,
  PRIMARY KEY (`UserID`, `ProductVariantID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `Transaction` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `UserID` INT NOT NULL,
  `Total_price` DECIMAL(12,2) NOT NULL,
  `Type` VARCHAR(255) NOT NULL,
  `Status` VARCHAR(50) NOT NULL DEFAULT 'PENDING',
  `SupplierID` INT NULL,
  `Paid_amount` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `Change_amount` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `Method` VARCHAR(255) NOT NULL,
  `Note` VARCHAR(1000) NULL,
  `Proof_image` VARCHAR(1000) NULL,
  `Updated_by` INT NOT NULL,
  `Updated_at` TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `Created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Delivered_at` TIMESTAMP NULL DEFAULT NULL,
  `Reference_transactionID` INT,
  `DeliveryInfoID` INT,
  `ShipperID` INT NULL,
  `VoucherID` INT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `Transaction_ProductVariant` (
  `TransactionID` INT NOT NULL,
  `ProductVariantID` INT NOT NULL,
  `Amount` INT NOT NULL,
  `UnitPrice` DECIMAL(12,2) NOT NULL,
  `Discount_rate` DECIMAL(5,2) NULL,
  `Discount_amount` DECIMAL(12,2) NULL,
  `Total` DECIMAL(12,2) NOT NULL,
  PRIMARY KEY (`TransactionID`, `ProductVariantID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `Feedback` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `Rating` INT NOT NULL,
  `Content` VARCHAR(255) NOT NULL,
  `Created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Updated_at` TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `UserID` INT NOT NULL,
  `ProductVariantID` INT NOT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `Answer` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `FeedbackID` INT NOT NULL,
  `Content` VARCHAR(255) NOT NULL,
  `Updated_at` TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `Created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `UserID` INT NOT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `ReturnRequest` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `Status` VARCHAR(50) NOT NULL DEFAULT 'ACTIVE',
  `Description` VARCHAR(255) NOT NULL,
  Image VARCHAR(255) NULL,
  BackImage VARCHAR(255) NULL,
  `Updated_at` TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `Created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `UserID` INT NOT NULL,
  `TransactionID` INT NOT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `ReturnRequest_ProductVariant` (
  `ReturnRequestID` INT NOT NULL,
  `ProductVariantID` INT NOT NULL,
  PRIMARY KEY (`ReturnRequestID`, `ProductVariantID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `DeliveryInfo` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `UserID` INT NOT NULL,
  `Recipient_name` VARCHAR(255) NOT NULL,
  `Recipient_phone` VARCHAR(255) NOT NULL,
  `Delivery_address` VARCHAR(255) NOT NULL,
  `Created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Updated_at` TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `Status` VARCHAR(50) NOT NULL DEFAULT 'PENDING',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
CREATE TABLE `Voucher` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `Code` VARCHAR(50) NOT NULL UNIQUE,
  `Discount_type` VARCHAR(50) NOT NULL,
  `Value` DECIMAL(12,2) NOT NULL,
  `Max_discount` DECIMAL(12,2) NULL,
  `Min_order_value` DECIMAL(12,2) NULL,
  `Max_uses_per_user` INT NOT NULL DEFAULT 1,
  `Usage_limit` INT NULL,
  `Used_count` INT NOT NULL DEFAULT 0,
  `Start_date` TIMESTAMP NOT NULL,
  `End_date` TIMESTAMP NOT NULL,
  `Status` VARCHAR(50) NOT NULL DEFAULT 'ACTIVE',
  `Created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Updated_at` TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `User_Voucher` (
  `UserID` INT NOT NULL,
  `VoucherID` INT NOT NULL,
  `Used_count` INT NOT NULL DEFAULT 0,
  `Saved_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Used_at` TIMESTAMP NULL DEFAULT NULL,
  PRIMARY KEY (`UserID`, `VoucherID`),
  FOREIGN KEY (`UserID`) REFERENCES `User`(`ID`) ON DELETE CASCADE,
  FOREIGN KEY (`VoucherID`) REFERENCES `Voucher`(`ID`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `Discount` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `Name` VARCHAR(255) NULL,
  `Description` VARCHAR(255) NULL,
  `Rate` DECIMAL(10,2) NOT NULL,
  `Start` TIMESTAMP NOT NULL,
  `End` TIMESTAMP NOT NULL,
  `Updated_at` TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `Created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 

CREATE TABLE `Discount_Product` (
  `DiscountID` INT NOT NULL,
  `ProductID` INT NOT NULL,
  PRIMARY KEY (`DiscountID`, `ProductID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 

CREATE TABLE `TransactionStatusHistory` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `TransactionID` INT NOT NULL,
  `UserID` INT NOT NULL,
  `Status` VARCHAR(50) NOT NULL DEFAULT 'PENDING',
  `Updated_at` TIMESTAMP NOT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 

CREATE TABLE `DeliveryStatusHistory` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `Updated_at` TIMESTAMP NOT NULL,
  `UserID` INT NOT NULL,
  `Status` VARCHAR(50) NOT NULL DEFAULT 'Shipping',
  `DeliveryInfoID` INT NOT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
-- =====================================================
-- Cancel Order Request Flow
-- =====================================================
-- Allows customers to request cancellation of an order while it has
-- not yet been delivered. Staff approves/rejects the request.
-- =====================================================

CREATE TABLE `CancelRequest` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `TransactionID` INT NOT NULL,
  `UserID` INT NOT NULL,
  `Reason` VARCHAR(100) NOT NULL,
  `CustomReason` VARCHAR(500) NULL,
  `BankName` VARCHAR(80) NULL,
  `BankAccountNumber` VARCHAR(40) NULL,
  `BankAccountHolder` VARCHAR(80) NULL,
  `Status` VARCHAR(50) NOT NULL DEFAULT 'PENDING',
  `StaffNote` VARCHAR(500) NULL,
  `Created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Updated_at` TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `Processed_by` INT NULL,
  `Processed_at` TIMESTAMP NULL,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `uq_CancelRequest_Transaction_Active` (`TransactionID`, `Status`),
  KEY `idx_CancelRequest_UserID` (`UserID`),
  KEY `idx_CancelRequest_Status` (`Status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
 
 CREATE TABLE `Complaint` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `TransactionID` INT NOT NULL,
  `UserID` INT NOT NULL,
  `Category` VARCHAR(50) NOT NULL,
  `CustomReason` VARCHAR(500) NULL,
  `Description` VARCHAR(2000) NULL,
  `Status` VARCHAR(50) NOT NULL DEFAULT 'OPEN',
  `Resolution` VARCHAR(50) NULL,
  `ResolutionNote` VARCHAR(1000) NULL,
  `Assigned_to` INT NULL,
  `Created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Updated_at` TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `Closed_at` TIMESTAMP NULL,
  `Closed_by` INT NULL,
  PRIMARY KEY (`ID`),
  KEY `idx_Complaint_TransactionID_Status` (`TransactionID`, `Status`),
  KEY `idx_Complaint_UserID` (`UserID`),
  KEY `idx_Complaint_Status` (`Status`),
  KEY `idx_Complaint_Assigned_to` (`Assigned_to`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `ComplaintMessage` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `ComplaintID` INT NOT NULL,
  `SenderID` INT NOT NULL,
  `SenderRole` VARCHAR(20) NOT NULL,
  `Content` VARCHAR(2000) NOT NULL,
  `Created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`),
  KEY `idx_ComplaintMessage_ComplaintID_Created` (`ComplaintID`, `Created_at`),
  KEY `idx_ComplaintMessage_SenderID` (`SenderID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
 
 
 CREATE TABLE StoreInformation (
    address VARCHAR(500),
    phone VARCHAR(50),
    email VARCHAR(255),
    facebook_url VARCHAR(500)
);

