ALTER TABLE `Complaint` ADD CONSTRAINT `fk_Complaint_Closed_by` FOREIGN KEY (`Closed_by`) REFERENCES `User` (`ID`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `ComplaintMessage` ADD CONSTRAINT `fk_ComplaintMessage_ComplaintID` FOREIGN KEY (`ComplaintID`) REFERENCES `Complaint` (`ID`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `ComplaintMessage` ADD CONSTRAINT `fk_ComplaintMessage_SenderID` FOREIGN KEY (`SenderID`) REFERENCES `User` (`ID`) ON DELETE CASCADE ON UPDATE CASCADE;
 
SET FOREIGN_KEY_CHECKS = 1;

CREATE INDEX `idx_Product_brand_status` ON `Product` (`BrandID`, `Status`);
CREATE INDEX `idx_ProductCategory_category_product` ON `Product_Category` (`CategoryID`, `ProductID`);
CREATE INDEX `idx_Transaction_user_status` ON `Transaction` (`UserID`, `Status`);
CREATE INDEX `idx_Feedback_productVatiant_created` ON `Feedback` (`ProductVariantID`, `Created_at`);
CREATE INDEX `idx_ReturnRequest_status` ON `ReturnRequest` (`Status`, `Created_at`);









-- One phone may belong to several feature categories.
SELECT `ID`, 1 FROM `Product` WHERE `Release_Year` >= 2024;

SELECT `ID`, 2 FROM `Product`
WHERE `Name` REGEXP 'POCO|ROG|RedMagic|Black Shark|Gaming|GT';

SELECT `ID`, 3 FROM `Product`
WHERE `Name` REGEXP 'Fold|Flip|Find N|Mix Fold';

SELECT `ID`, 4 FROM `Product`
WHERE `Name` REGEXP 'Pro|Ultra|Find X|Note';

SELECT `ID`, 5 FROM `Product`
WHERE `Name` REGEXP 'Galaxy M|Galaxy A|Redmi|POCO|OPPO A';

SELECT pv.ID, 8 + ((pv.ProductID + pv.ID) MOD 13), 2, 50, 'ACTIVE' FROM ProductVariant pv;

SELECT 1 + ((pv.ProductID - 1) MOD 3), pv.ID FROM ProductVariant pv;












